        if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
        var options = {
            id: "test1",
            type: "window",
            width: "100px",
            height: "100px",
            top: 10 + "px",
            left: 10 + "px",
            popupName: "TestTTTTTTT",
            modal: true,
            useIFrame: true,
